-- 426 — Publish the opt-in public contact footer on the unowned Core catalog only.
-- Generated by scripts/liquid-parity/build-core-public-contact-footer.mjs.
-- Existing site-owned themes, editor drafts, and published releases are immutable.
BEGIN;
SET LOCAL search_path = pg_catalog, public;
DO $core_footer_426$
DECLARE
  v_template jsonb;
  v_bundle jsonb;
  v_current jsonb;
  v_from jsonb := $corefooterjson${"path":"sections/footer.liquid","source":"<footer class=\"lb-footer\" data-section-id=\"{{ section.id }}\">\n  <div class=\"lb-footer__grid\">\n    <div class=\"lb-footer__brand\">\n      <h3>{{ section.settings.storeName | default: shop.name }}</h3>\n      {% if section.settings.tagline %}<p>{{ section.settings.tagline }}</p>{% endif %}\n      {% if section.settings.instagramUrl != blank or section.settings.facebookUrl != blank or section.settings.twitterUrl != blank %}\n      <div class=\"lb-footer__social\">\n        {% if section.settings.instagramUrl != blank %}<a href=\"{{ section.settings.instagramUrl }}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Instagram\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\" ry=\"5\"></rect><circle cx=\"12\" cy=\"12\" r=\"4\"></circle><circle cx=\"17.5\" cy=\"6.5\" r=\"1\"></circle></svg></a>{% endif %}\n        {% if section.settings.facebookUrl != blank %}<a href=\"{{ section.settings.facebookUrl }}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Facebook\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M15 4h-2a4 4 0 0 0-4 4v3H6v4h3v7h4v-7h3l1-4h-4V8a1 1 0 0 1 1-1h3z\"></path></svg></a>{% endif %}\n        {% if section.settings.twitterUrl != blank %}<a href=\"{{ section.settings.twitterUrl }}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Twitter/X\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><line x1=\"4\" y1=\"4\" x2=\"20\" y2=\"20\"></line><line x1=\"20\" y1=\"4\" x2=\"4\" y2=\"20\"></line></svg></a>{% endif %}\n      </div>\n      {% endif %}\n    </div>\n    {% if section.blocks.size > 0 %}\n    <div class=\"lb-footer__col\"><h4>Quick links</h4><nav>{% for block in section.blocks %}<a href=\"{{ block.settings.href | store_url }}\">{{ block.settings.label }}</a>{% endfor %}</nav></div>\n    {% elsif linklists.footer_menu.links.size > 0 %}\n    <div class=\"lb-footer__col\"><h4>Quick links</h4><nav>{% for link in linklists.footer_menu.links %}<a href=\"{{ link.url | store_url }}\"{% if link.active %} aria-current=\"page\"{% endif %}>{{ link.title }}</a>{% endfor %}</nav></div>\n    {% endif %}\n    {% if shop.policies.size > 0 %}<div class=\"lb-footer__col\">\n      <h4>Policies</h4>\n      <nav>\n        {% if shop.policies contains 'privacy' %}<a href=\"{{ routes.root_url }}/privacy\">Privacy policy</a>{% endif %}\n        {% if shop.policies contains 'terms' %}<a href=\"{{ routes.root_url }}/terms\">Terms of service</a>{% endif %}\n        {% if shop.policies contains 'shipping' %}<a href=\"{{ routes.root_url }}/shipping\">Shipping policy</a>{% endif %}\n        {% if shop.policies contains 'refund' or shop.policies contains 'returns' %}<a href=\"{{ routes.root_url }}/returns\">Returns policy</a>{% endif %}\n      </nav>\n    </div>{% endif %}\n    <div class=\"lb-footer__col\">\n      <h4>Contact</h4>\n      {% if section.settings.contactEmail != blank %}<p><a href=\"mailto:{{ section.settings.contactEmail }}\">{{ section.settings.contactEmail }}</a></p>{% endif %}\n      {% if section.settings.contactPhone != blank %}<p><a href=\"tel:{{ section.settings.contactPhone }}\">{{ section.settings.contactPhone }}</a></p>{% endif %}\n      <a href=\"{{ routes.contact_url }}\">Contact us</a>\n    </div>\n  </div>\n  <div class=\"lb-footer__bottom\">\n    <p>&copy; {{ shop.name }}. All rights reserved.</p>\n    <a class=\"lb-footer__watermark\" href=\"https://letbuyy.com\" target=\"_blank\" rel=\"noopener noreferrer\">Powered by LetBuyy</a>\n  </div>\n</footer>\n{% schema %}\n{\n  \"name\": \"Footer\",\n  \"settings\": [\n    {\n      \"id\": \"storeName\",\n      \"type\": \"text\",\n      \"label\": \"Store name\"\n    },\n    {\n      \"id\": \"tagline\",\n      \"type\": \"text\",\n      \"label\": \"Tagline\"\n    },\n    {\n      \"id\": \"contactEmail\",\n      \"type\": \"text\",\n      \"label\": \"Contact email\"\n    },\n    {\n      \"id\": \"contactPhone\",\n      \"type\": \"text\",\n      \"label\": \"Contact phone\"\n    },\n    {\n      \"id\": \"instagramUrl\",\n      \"type\": \"url\",\n      \"label\": \"Instagram URL\"\n    },\n    {\n      \"id\": \"facebookUrl\",\n      \"type\": \"url\",\n      \"label\": \"Facebook URL\"\n    },\n    {\n      \"id\": \"twitterUrl\",\n      \"type\": \"url\",\n      \"label\": \"Twitter/X URL\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"link\",\n      \"name\": \"Link\",\n      \"settings\": [\n        {\n          \"id\": \"label\",\n          \"type\": \"text\",\n          \"label\": \"Label\"\n        },\n        {\n          \"id\": \"href\",\n          \"type\": \"url\",\n          \"label\": \"URL\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Footer\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ]\n}\n{% endschema %}","schema":{"name":"Footer","tag":"section","settings":[{"type":"text","label":"Store name","id":"storeName"},{"type":"text","label":"Tagline","id":"tagline"},{"type":"text","label":"Contact email","id":"contactEmail"},{"type":"text","label":"Contact phone","id":"contactPhone"},{"type":"url","label":"Instagram URL","id":"instagramUrl"},{"type":"url","label":"Facebook URL","id":"facebookUrl"},{"type":"url","label":"Twitter/X URL","id":"twitterUrl"}],"blocks":[{"type":"link","name":"Link","settings":[{"type":"text","label":"Label","id":"label"},{"type":"url","label":"URL","id":"href"}]}],"presets":[{"name":"Footer","settings":{},"blocks":[]}],"enabled_on":{"templates":["*"]},"disabled_on":{"templates":[]}}}$corefooterjson$::jsonb;
  v_to jsonb := $corefooterjson${"path":"sections/footer.liquid","source":"<footer class=\"lb-footer\" data-section-id=\"{{ section.id }}\">\n  <div class=\"lb-footer__grid\">\n    <div class=\"lb-footer__brand\">\n      <h3>{{ section.settings.storeName | default: shop.name }}</h3>\n      {% if section.settings.tagline %}<p>{{ section.settings.tagline }}</p>{% endif %}\n      {% if section.settings.instagramUrl != blank or section.settings.facebookUrl != blank or section.settings.twitterUrl != blank %}\n      <div class=\"lb-footer__social\">\n        {% if section.settings.instagramUrl != blank %}<a href=\"{{ section.settings.instagramUrl }}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Instagram\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\" ry=\"5\"></rect><circle cx=\"12\" cy=\"12\" r=\"4\"></circle><circle cx=\"17.5\" cy=\"6.5\" r=\"1\"></circle></svg></a>{% endif %}\n        {% if section.settings.facebookUrl != blank %}<a href=\"{{ section.settings.facebookUrl }}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Facebook\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M15 4h-2a4 4 0 0 0-4 4v3H6v4h3v7h4v-7h3l1-4h-4V8a1 1 0 0 1 1-1h3z\"></path></svg></a>{% endif %}\n        {% if section.settings.twitterUrl != blank %}<a href=\"{{ section.settings.twitterUrl }}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Twitter/X\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><line x1=\"4\" y1=\"4\" x2=\"20\" y2=\"20\"></line><line x1=\"20\" y1=\"4\" x2=\"4\" y2=\"20\"></line></svg></a>{% endif %}\n      </div>\n      {% endif %}\n    </div>\n    {% if section.blocks.size > 0 %}\n    <div class=\"lb-footer__col\"><h4>Quick links</h4><nav>{% for block in section.blocks %}<a href=\"{{ block.settings.href | store_url }}\">{{ block.settings.label }}</a>{% endfor %}</nav></div>\n    {% elsif linklists.footer_menu.links.size > 0 %}\n    <div class=\"lb-footer__col\"><h4>Quick links</h4><nav>{% for link in linklists.footer_menu.links %}<a href=\"{{ link.url | store_url }}\"{% if link.active %} aria-current=\"page\"{% endif %}>{{ link.title }}</a>{% endfor %}</nav></div>\n    {% endif %}\n    {% if shop.policies.size > 0 %}<div class=\"lb-footer__col\">\n      <h4>Policies</h4>\n      <nav>\n        {% if shop.policies contains 'privacy' %}<a href=\"{{ routes.root_url }}/privacy\">Privacy policy</a>{% endif %}\n        {% if shop.policies contains 'terms' %}<a href=\"{{ routes.root_url }}/terms\">Terms of service</a>{% endif %}\n        {% if shop.policies contains 'shipping' %}<a href=\"{{ routes.root_url }}/shipping\">Shipping policy</a>{% endif %}\n        {% if shop.policies contains 'refund' or shop.policies contains 'returns' %}<a href=\"{{ routes.root_url }}/returns\">Returns policy</a>{% endif %}\n      </nav>\n    </div>{% endif %}\n    <div class=\"lb-footer__col\">\n      <h4>Contact</h4>\n      {% assign contact_email = section.settings.contactEmail | default: shop.contact_email %}\n      {% if contact_email == \"help@letbuyy.com\" %}{% assign contact_email = shop.contact_email %}{% endif %}\n      {% assign contact_phone = section.settings.contactPhone | default: shop.contact_phone %}\n      {% if contact_email != blank %}<p><a href=\"mailto:{{ contact_email }}\">{{ contact_email }}</a></p>{% endif %}\n      {% if contact_phone != blank %}<p><a href=\"tel:{{ contact_phone }}\">{{ contact_phone }}</a></p>{% endif %}\n      <a href=\"{{ routes.contact_url }}\">Contact us</a>\n    </div>\n  </div>\n  <div class=\"lb-footer__bottom\">\n    <p>&copy; {{ shop.name }}. All rights reserved.</p>\n    <a class=\"lb-footer__watermark\" href=\"https://letbuyy.com\" target=\"_blank\" rel=\"noopener noreferrer\">Powered by LetBuyy</a>\n  </div>\n</footer>\n{% schema %}\n{\n  \"name\": \"Footer\",\n  \"settings\": [\n    {\n      \"id\": \"storeName\",\n      \"type\": \"text\",\n      \"label\": \"Store name\"\n    },\n    {\n      \"id\": \"tagline\",\n      \"type\": \"text\",\n      \"label\": \"Tagline\"\n    },\n    {\n      \"id\": \"contactEmail\",\n      \"type\": \"text\",\n      \"label\": \"Contact email\"\n    },\n    {\n      \"id\": \"contactPhone\",\n      \"type\": \"text\",\n      \"label\": \"Contact phone\"\n    },\n    {\n      \"id\": \"instagramUrl\",\n      \"type\": \"url\",\n      \"label\": \"Instagram URL\"\n    },\n    {\n      \"id\": \"facebookUrl\",\n      \"type\": \"url\",\n      \"label\": \"Facebook URL\"\n    },\n    {\n      \"id\": \"twitterUrl\",\n      \"type\": \"url\",\n      \"label\": \"Twitter/X URL\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"link\",\n      \"name\": \"Link\",\n      \"settings\": [\n        {\n          \"id\": \"label\",\n          \"type\": \"text\",\n          \"label\": \"Label\"\n        },\n        {\n          \"id\": \"href\",\n          \"type\": \"url\",\n          \"label\": \"URL\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Footer\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ]\n}\n{% endschema %}","schema":{"name":"Footer","tag":"section","settings":[{"type":"text","label":"Store name","id":"storeName"},{"type":"text","label":"Tagline","id":"tagline"},{"type":"text","label":"Contact email","id":"contactEmail"},{"type":"text","label":"Contact phone","id":"contactPhone"},{"type":"url","label":"Instagram URL","id":"instagramUrl"},{"type":"url","label":"Facebook URL","id":"facebookUrl"},{"type":"url","label":"Twitter/X URL","id":"twitterUrl"}],"blocks":[{"type":"link","name":"Link","settings":[{"type":"text","label":"Label","id":"label"},{"type":"url","label":"URL","id":"href"}]}],"presets":[{"name":"Footer","settings":{},"blocks":[]}],"enabled_on":{"templates":["*"]},"disabled_on":{"templates":[]}}}$corefooterjson$::jsonb;
BEGIN
  SELECT default_template INTO v_template FROM public.themes
   WHERE slug = 'letbuyy-core' AND owned_by_site_id IS NULL
     AND NOT COALESCE(is_site_private, false) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unowned canonical Core catalog is unavailable'; END IF;
  v_bundle := v_template->'liquidBundle';
  IF v_bundle#>>'{package,slug}' IS DISTINCT FROM 'letbuyy-core-liquid'
     OR v_bundle#>>'{renderer,engine}' IS DISTINCT FROM 'liquid' THEN
    RAISE EXCEPTION 'Unexpected Core package or renderer';
  END IF;
  v_current := v_bundle#>'{sections,footer}';
  IF v_current IS DISTINCT FROM v_from AND v_current IS DISTINCT FROM v_to THEN
    RAISE EXCEPTION 'Unexpected Core catalog footer';
  END IF;
  IF v_current IS NOT DISTINCT FROM v_from THEN
    v_bundle := jsonb_set(v_bundle, '{sections,footer}', v_to, false);
    UPDATE public.themes
       SET default_template = jsonb_set(v_template, '{liquidBundle}', v_bundle, false),
           updated_at = now()
     WHERE slug = 'letbuyy-core' AND owned_by_site_id IS NULL
       AND NOT COALESCE(is_site_private, false);
  END IF;
END;
$core_footer_426$;
COMMIT;
